+
+  <main id="maincontent" class="shell" tabindex="-1">
+    <section class="quiz-card" aria-labelledby="quiz-title">
+      <h2 id="quiz-title" class="visually-hidden">Quiz questions</h2>
+      <div id="quiz-status" class="quiz-status" role="status" aria-live="polite" aria-atomic="true">
