+    </section>
+  </main>
+
+  <script>
+    const quizData = [
+      {
+        id: "q1",
+        prompt: "Which of these are programming languages?",
+        help: "Select all that are used to write executable programs.",
+        choices: [
+          { label: "Python", value: "python", correct: true },
+          { label: "Java", value: "java", correct: true },
+          { label: "HTML", value: "html", correct: false },
+          { label: "CSS", value: "css", correct: false }
+        ]
+      },
+      {
+        id: "q2",
+        prompt: "Which of these are statically typed languages?",
+        choices: [
+          { label: "TypeScript", value: "typescript", correct: true },
+          { label: "Java", value: "java", correct: true },
+          { label: "Python", value: "python", correct: false },
+          { label: "Ruby", value: "ruby", correct: false }
+        ]
+      },
+      {
+        id: "q3",
+        prompt: "Which of these are commonly used for scripting and automation?",
+        choices: [
+          { label: "Python", value: "python", correct: true },
+          { label: "Bash", value: "bash", correct: true },
+          { label: "JavaScript", value: "javascript", correct: true },
+          { label: "C", value: "c", correct: false }
+        ]
+      }
+    ];
+
+    const form = document.getElementById("quiz-form");
+    const status = document.getElementById("quiz-status");
+
+    function escapeHtml(value) {
+      return String(value)
+        .replaceAll("&", "&amp;")
+        .replaceAll("<", "&lt;")
+        .replaceAll(">", "&gt;")
+        .replaceAll('"', "&quot;")
+        .replaceAll("'", "&#39;");
+    }
+
+    function choiceTemplate(questionId, choice, questionIndex, choiceIndex) {
+      const id = `${questionId}-${choice.value}`;
+      return `
+        <div class="option">
+          <input id="${id}" name="${questionId}" type="checkbox" value="${choice.value}">
+          <label for="${id}">
+            <span>${escapeHtml(choice.label)}</span>
+          </label>
+        </div>
+      `;
+    }
+
+    function questionTemplate(question, index) {
+      const helpId = question.help ? `${question.id}-help` : "";
+      return `
+        <div class="form-field">
+          <fieldset class="question-card" data-question="${question.id}" ${helpId ? `aria-describedby="${helpId}"` : ""}>
+            <legend>
+              Question ${index + 1}: ${escapeHtml(question.prompt)}
+            </legend>
+            ${question.help ? `<p class="help-text" id="${helpId}">${escapeHtml(question.help)}</p>` : ""}
+            <div class="options" role="presentation">
+              ${question.choices.map((choice, choiceIndex) => choiceTemplate(question.id, choice, index, choiceIndex)).join("")}
+            </div>
+            <p class="feedback" id="${question.id}-feedback" aria-hidden="true"></p>
+          </fieldset>
+        </div>
+      `;
+    }
+
+    function appTemplate(questions) {
+      return `
+        ${questions.map(questionTemplate).join("")}
+        <div class="actions">
+          <button class="submit-button" type="submit">Check my answers</button>
+        </div>
+      `;
+    }
+
+    function getSelectedValues(questionId) {
+      return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map((input) => input.value).sort();
+    }
+
+    function getCorrectValues(question) {
+      return question.choices.filter((choice) => choice.correct).map((choice) => choice.value).sort();
+    }
+
+    function arraysMatch(left, right) {
+      return left.length === right.length && left.every((value, index) => value === right[index]);
+    }
+
+    function renderQuizResults(results) {
+      let correctCount = 0;
+
+      results.forEach((result) => {
+        const fieldset = form.querySelector(`[data-question="${result.id}"]`);
+        const feedback = form.querySelector(`#${result.id}-feedback`);
+
+        fieldset.dataset.state = result.correct ? "correct" : "incorrect";
+        feedback.textContent = result.correct
+          ? "Correct."
+          : `Not quite. You selected ${result.selectedCount} option${result.selectedCount === 1 ? "" : "s"}.`;
+        feedback.className = `feedback ${result.correct ? "is-correct" : "is-incorrect"}`;
+        feedback.removeAttribute("aria-hidden");
+
+        if (result.correct) {
+          correctCount += 1;
+        }
+      });
+
+      const total = results.length;
+      status.textContent = `You got ${correctCount} out of ${total} questions correct.`;
+    }
+
+    form.innerHTML = appTemplate(quizData);
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const results = quizData.map((question) => {
+        const selected = getSelectedValues(question.id);
+        const correct = arraysMatch(selected, getCorrectValues(question));
+
+        return {
+          id: question.id,
+          correct,
+          selectedCount: selected.length
+        };
+      });
+
+      renderQuizResults(results);
+    });
+  </script>
+</body>
+</html>
